#[derive(Debug, Clone, PartialEq, Eq)]
struct Interval {
    min: f64,
    max: f64,
}

impl Interval {
    // Helper constructor for an interval, expecting min < max
    fn new(min: f64, max: f64) -> Self {
        assert!(min < max, "Interval minimum must be strictly less than maximum.");
        Self { min, max }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ChebyshevPoly {
    coefficients: Vec<i32>,
    domain: Interval,
    window: Interval,
}

fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Precondition: coef is non-empty; 
    // This could be asserted if desired, but problem states input is positive size
    
    // Convert coefficients from i8 to i32 preserving order and length
    let coefficients: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Construct default domain and window intervals [-1, 1] which are valid intervals
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coefficients,
        domain,
        window,
    }
}